unsafe extern "C" fn game_movewms(agent: &mut L2CAgentBase) {
    let lua_state = agent.lua_state_agent;
    let boma = agent.boma();
    if is_excute(agent) {
        AttackModule::enable_safe_pos(boma);
        let owner_module_accessor = &mut *sv_battle_object::module_accessor((agent.get_int(*WEAPON_INSTANCE_WORK_ID_INT_LINK_OWNER)) as u32);
        VarModule::set_flag(
            agent.battle_object, 
            vars::shotos::instance::EX_SPECIAL_USED,
            VarModule::is_flag(owner_module_accessor.object(), vars::shotos::instance::EX_SPECIAL_USED)
        );
        VarModule::set_flag(
            agent.battle_object, 
            vars::shotos::instance::MAGIC_SERIES_CANCEL,
            VarModule::is_flag(owner_module_accessor.object(), vars::shotos::instance::MAGIC_SERIES_CANCEL)
        );

        ATTACK(agent, 0, 0, Hash40::new("top"), 9.0, 0, 16, 0, 38, 3.5, 0.0, 0.5, -0.5, Some(0.0), Some(-5.2), Some(-0.5), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_G, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
        ATTACK(agent, 1, 0, Hash40::new("top"), 9.0, 0, 16, 0, 38, 2.8, 0.0, 0.0, 0.0, Some(0.0), Some(0.0), Some(-2.5), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_G, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
        ATTACK(agent, 2, 0, Hash40::new("top"), 9.0, 60, 16, 0, 38, 2.8, 0.0, 0.0, 0.0, Some(0.0), Some(0.0), Some(-2.5), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_A, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
        if VarModule::is_flag(agent.battle_object, vars::shotos::instance::EX_SPECIAL_USED) {
            let speed = KineticModule::get_sum_speed3f(boma, *KINETIC_ENERGY_RESERVE_ATTRIBUTE_ALL);
            KineticModule::mul_speed(boma, &Vector3f{x: 2.3 / speed.x.abs(), y: 0.0, z: 0.0}, *KINETIC_ENERGY_RESERVE_ATTRIBUTE_ALL);
            agent.set_int(35, *WEAPON_INSTANCE_WORK_ID_INT_INIT_LIFE);
            agent.set_int(35, *WEAPON_INSTANCE_WORK_ID_INT_LIFE);
        }
        if (VarModule::is_flag(owner_module_accessor.object(), vars::shotos::instance::SPECIAL_N_HADOKEN_AIR)) {
            let lr = PostureModule::lr(owner_module_accessor);
            GroundModule::set_rhombus_offset(boma, &Vector2f{x: -4.0 * lr, y: 3.0}); // fix the hado falling through the stage
            KineticModule::reflect_speed(boma, &Vector3f{x: 0.42262, y: lr * 0.90631, z: 0.0}, *KINETIC_ENERGY_RESERVE_ATTRIBUTE_ALL); // send the hado at a -45degree angle
            let life = agent.get_int(*WEAPON_INSTANCE_WORK_ID_INT_LIFE) * 3/4; // reduce hado lifetime
            agent.set_int(life, *WEAPON_INSTANCE_WORK_ID_INT_INIT_LIFE);
            agent.set_int(life, *WEAPON_INSTANCE_WORK_ID_INT_LIFE);
            VarModule::off_flag(owner_module_accessor.object(), vars::shotos::instance::SPECIAL_N_HADOKEN_AIR);
        }
        else{
            GroundModule::set_rhombus_offset(boma, &Vector2f{x: 0.0, y: 0.0});
        }
    }

    wait(lua_state, 6.0);
    if is_excute(agent) {
        ATTACK(agent, 0, 0, Hash40::new("top"), 9.0, 0, 16, 0, 38, 3.0, 0.0, 0.0, 0.0, Some(0.0), Some(0.0), Some(-2.5), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_G, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
        ATTACK(agent, 1, 0, Hash40::new("top"), 9.0, 0, 16, 0, 38, 2.5, 0.0, 1.3, -1.25, Some(0.0), Some(-1.3), Some(-1.25), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_G, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
        ATTACK(agent, 2, 0, Hash40::new("top"), 9.0, 60, 16, 0, 38, 2.5, 0.0, 1.3, -1.25, Some(0.0), Some(-1.3), Some(-1.25), 1.0, 1.2, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_F, false, 0, 0.0, 0, true, true, false, false, false, *COLLISION_SITUATION_MASK_A, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), *ATTACK_SOUND_LEVEL_L, *COLLISION_SOUND_ATTR_KEN_PUNCH, *ATTACK_REGION_ENERGY);
    }
}

